// 3. גיבוי מצב האפליקציה (26.10.26): עותק הלוח לא כולל את ההגדרות של הסקריפט (מצב כל מתאמן, שיחות, משימות, אחוז שומן...).
// קובץ JSON יומי באותה תיקייה, בלי מפתחות וסודות, נשמרים 14 אחרונים (ישנים לפח). שחזור ידני בלבד: restoreAppState_(fileId) משלים רק מה שחסר
const STATE_SECRET_ = /key|vapid|secret|pass|token/i;
function backupAppState_(dir) { const all = PropertiesService.getScriptProperties().getProperties(), out = {};
  Object.keys(all).forEach(k => { if (!STATE_SECRET_.test(k.split(':')[0])) out[k] = all[k]; });
  dir.createFile('גיבוי מצב אפליקציה ' + Utilities.formatDate(new Date(), 'Asia/Jerusalem', 'yyyy-MM-dd HH:mm') + '.json', JSON.stringify({ at: new Date().toISOString(), props: out }), 'application/json');
  const files = []; const f = dir.getFiles(); while (f.hasNext()) { const x = f.next(); if (x.getName().indexOf('גיבוי מצב אפליקציה ') === 0) files.push(x); }
  files.sort((a, b) => b.getDateCreated() - a.getDateCreated()).slice(14).forEach(x => x.setTrashed(true));
  return Object.keys(out).length; }
function restoreAppState_(fileId, overwrite) { const j = JSON.parse(DriveApp.getFileById(fileId).getBlob().getDataAsString()), P = PropertiesService.getScriptProperties(), cur = P.getProperties(); let n = 0;
  Object.keys(j.props || {}).forEach(k => { if (STATE_SECRET_.test(k.split(':')[0])) return; if (overwrite || cur[k] == null) { P.setProperty(k, j.props[k]); n++; } }); return n; }
